{
  "title": "考试前的秘籍",
  "scene": "今天是期末考试，你一早来到教室却发现讲台上有一本笔记本。翻开一看，里面记录着大量考试重点和解题技巧，似乎是老师不小心留下的。你环顾四周，注意到教室唯一的摄像头被一块布挡住了，而门外的走廊上有一名保安正在巡逻。你心里一阵窃喜，但同时也感到不安。",
  "goal": "考试前获取优势，但避免作弊被抓",
  "clue": "摄像头被布挡住了，但保安在巡逻。",
  "choices": [
    {
      "id": "A",
      "text": "偷偷带走笔记本",
      "outcome": "你迅速拿起笔记本藏在书包里，准备离开教室。但刚走到门口，保安突然推门而入，发现你手中拿着的笔记本。你被带到校长室，考试成绩被取消。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "拍照保存",
      "outcome": "你谨慎地用手机拍下笔记本中的内容，确保不会被发现。考试时，你凭借记忆中的内容顺利解答了大部分题目，但因为紧张忘记了一些关键点，最终成绩还算不错。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "报告老师",
      "outcome": "你决定将笔记本放回原处，然后去办公室报告老师。老师非常感激你的正直，不仅表扬了你，还额外给了你一些考试指导，让你在考试中表现得非常出色。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
